"""Algorithm 1: inversion of the edge fraction (the effective exponent)."""

from __future__ import annotations

import math
from typing import Optional


def head_mass(b: float, t: float) -> float:
    """Closed form of int_0^t (1+x)^(-b) dx; logarithmic at b = 1."""
    if abs(b - 1.0) < 1e-14:
        return math.log(1.0 + t)
    return ((1.0 + t) ** (1.0 - b) - 1.0) / (1.0 - b)


def edge_frac(b: float, t: float) -> float:
    """Normalised cumulative mass F(b, t) = H(b, t) / H(b, 1) in (0, 1)."""
    return head_mass(b, t) / head_mass(b, 1.0)


def bracket(target: float, t: float,
            lo: float = -1.0, hi: float = 1.0,
            max_expansions: int = 200) -> tuple[float, float]:
    """Expand a bracket [lo, hi] until F(lo, t) < target < F(hi, t).

    Well posed by two facts: F(., t) is strictly increasing (rigidity), and its
    range on the whole real line is (0, 1) -- it tends to 1 as b -> +infinity
    (the spike limit) and to 0 as b -> -infinity."""
    for _ in range(max_expansions):
        if edge_frac(lo, t) < target < edge_frac(hi, t):
            return lo, hi
        if edge_frac(lo, t) >= target:
            lo = 2.0 * lo - hi
        if edge_frac(hi, t) <= target:
            hi = 2.0 * hi - lo
    raise ValueError("target edge fraction not attainable: it must lie in (0, 1)")


def effective_exponent(target: float, t: float,
                       tol: float = 1e-12,
                       max_iter: int = 400) -> Optional[float]:
    """Return the unique exponent b with F(b, t) = target, or None if the
    target is outside (0, 1).

    Complexity: O(log((hi - lo) / tol)) evaluations of a closed-form
    expression, i.e. about 50 iterations for double precision. Uniqueness is
    guaranteed by strict monotonicity of F in the exponent; convergence is
    unconditional because bisection needs only a sign change."""
    if not (0.0 < target < 1.0) or not (0.0 < t < 1.0):
        return None
    lo, hi = bracket(target, t)
    for _ in range(max_iter):
        mid = 0.5 * (lo + hi)
        if edge_frac(mid, t) < target:
            lo = mid
        else:
            hi = mid
        if hi - lo < tol:
            break
    return 0.5 * (lo + hi)


if __name__ == "__main__":
    for (alpha, t) in ((0.1620, 0.1), (0.1415, 0.1), (0.5, 0.5), (0.95, 0.1)):
        b = effective_exponent(alpha, t)
        print(f"F(b, {t}) = {alpha:.4f}  ->  b = {b:.6f}  "
              f"(check {edge_frac(b, t):.6f})")

"""Algorithm 3: spike-weight estimation with a censored spike exponent.

The narrow-spike limit says that as the spike exponent b2 grows, the mixture's
edge fraction converges to (1 - w) F(b1, t) + w, independently of b2. Hence the
weight w is identified by the excess of the observed edge mass over the bulk
prediction, while b2 is only bounded from below. This routine returns the
weight estimate together with an honest lower bound for the spike exponent, and
never reports a point estimate for b2.
"""

from __future__ import annotations

import math
from typing import List, Sequence, Tuple


def head_mass(b: float, t: float) -> float:
    if abs(b - 1.0) < 1e-14:
        return math.log(1.0 + t)
    return ((1.0 + t) ** (1.0 - b) - 1.0) / (1.0 - b)


def edge_frac(b: float, t: float) -> float:
    return head_mass(b, t) / head_mass(b, 1.0)


def mix_frac(w: float, b1: float, b2: float, t: float) -> float:
    return (1.0 - w) * edge_frac(b1, t) + w * edge_frac(b2, t)


def spike_weight(observed_edge: float, bulk_exponent: float,
                 t: float) -> float:
    """Narrow-spike-limit estimator w_hat = (F_obs - F(b1,t)) / (1 - F(b1,t)).

    Consistent whenever the spike is sharper than the resolution of the window
    grid. Cost O(1)."""
    bulk = edge_frac(bulk_exponent, t)
    return (observed_edge - bulk) / (1.0 - bulk)


def spike_exponent_lower_bound(observed_edge: float, bulk_exponent: float,
                               weight: float, t: float,
                               tolerance: float,
                               b_max: float = 400.0) -> float:
    """Smallest spike exponent consistent with the data to within `tolerance`.

    Because b2 |-> mix_frac(w, b1, b2, t) is strictly increasing (rigidity) and
    converges to the narrow-spike limit, the set of admissible b2 is an upper
    ray, and its left endpoint is found by bisection. The routine returns that
    endpoint: values above it are statistically indistinguishable, so no point
    estimate is meaningful. Cost O(log(1/eps))."""
    def gap(b2: float) -> float:
        return abs(mix_frac(weight, bulk_exponent, b2, t) - observed_edge)

    lo, hi = bulk_exponent + 1e-6, b_max
    if gap(hi) > tolerance:
        return math.inf  # no admissible spike exponent at this tolerance
    for _ in range(200):
        mid = 0.5 * (lo + hi)
        if gap(mid) > tolerance:
            lo = mid
        else:
            hi = mid
    return hi


def censoring_report(observed_edge: float, bulk_exponent: float, t: float,
                     tolerance: float = 2e-3) -> dict:
    """Full report: weight, spike lower bound, and the plateau evidence."""
    w = spike_weight(observed_edge, bulk_exponent, t)
    lb = spike_exponent_lower_bound(observed_edge, bulk_exponent, w, t, tolerance)
    plateau: List[Tuple[float, float]] = [
        (b2, mix_frac(w, bulk_exponent, b2, t))
        for b2 in (5.0, 10.0, 20.0, 40.0, 100.0, 1000.0)
    ]
    return {
        "window": t,
        "bulk_exponent": bulk_exponent,
        "observed_edge_fraction": observed_edge,
        "bulk_only_prediction": edge_frac(bulk_exponent, t),
        "spike_weight": w,
        "spike_exponent_lower_bound": lb,
        "spike_exponent_point_estimate": None,  # deliberately not identified
        "plateau": plateau,
    }


def sensitivity_to_bulk(observed_edge: float, t: float,
                        bulk_grid: Sequence[float]) -> List[Tuple[float, float]]:
    """How the recovered weight depends on the assumed bulk exponent."""
    return [(b1, spike_weight(observed_edge, b1, t)) for b1 in bulk_grid]


if __name__ == "__main__":
    rep = censoring_report(observed_edge=0.1620, bulk_exponent=0.573, t=0.1)
    for k, v in rep.items():
        print(f"{k:32s}: {v}")
    print("\nsensitivity of the weight to the bulk exponent:")
    for b1, w in sensitivity_to_bulk(0.1620, 0.1, (0.41, 0.573, 0.77)):
        print(f"   b1 = {b1:5.3f}  ->  w = {w:.4f}")
